mapper.select:
SELECT MIN(t.id) AS id, t.bus_no AS busNo, CASE t.status_enum WHEN 'DRAFT' THEN '草稿' WHEN 'PENDING' THEN '待审核' WHEN 'PENDING_APPROVAL' THEN '待审批' WHEN 'APPROVED' THEN '已审批' WHEN 'APPROVAL' THEN '已审批' WHEN 'AGREE' THEN '同意' WHEN 'REJECTED' THEN '已驳回' WHEN 'REJECT' THEN '已驳回' WHEN 'WITHDRAWN' THEN '已撤回' WHEN 'WITHDRAW' THEN '已撤回' ELSE t.status_enum END AS statusName, creator.name AS createByName, approver.name AS approverName, COALESCE(t.apply_time, MIN(t.created_at)) AS applyTime, CONCAT(IFNULL(source_org.name, '未知来源'), ' → ', IFNULL(purpose_org.name, '未知目的')) AS transferPath, IFNULL(SUM(CASE WHEN t.item_quantity > 0 THEN t.total_price ELSE 0 END), 0) AS totalPrice FROM wkf_supply_request t LEFT JOIN adm_practitioner creator ON creator.id = t.created_by AND creator.is_deleted = 0 LEFT JOIN adm_practitioner approver ON approver.id = t.approver_id AND approver.is_deleted = 0 LEFT JOIN adm_organization source_org ON source_org.id = t.source_location_id AND source_org.is_deleted = 0 LEFT JOIN adm_organization purpose_org ON purpose_org.id = t.purpose_location_id AND purpose_org.is_deleted = 0 WHERE t.is_deleted = 0 AND t.type_enum IN ('PHARMACY_STOCK_IN', 'INVENTORY_IN')
AND t.bus_no LIKE CONCAT('%', #{busNo}, '%')
AND t.source_location_id = #{sourceLocationId}
AND t.purpose_location_id = #{purposeLocationId}
AND t.status_enum = #{statusEnum}
AND t.apply_time >= #{startTime}
AND t.apply_time <= #{endTime}
GROUP BY t.bus_no, t.status_enum, creator.name, approver.name, t.apply_time, source_org.name, purpose_org.name ORDER BY COALESCE(t.apply_time, MIN(t.created_at)) DESC, t.bus_no DESC
